/**
 * OP.GG MCP client. This is the ONLY module that knows the data comes from
 * OP.GG; the rest of the app must use the neutral types in ./types.ts.
 *
 * Tool names/params: see docs/opgg-tools.json (generated by
 * scripts/list-opgg-tools.ts). Conversion to neutral types arrives in Phase 1.
 */
import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { StreamableHTTPClientTransport } from "@modelcontextprotocol/sdk/client/streamableHttp.js";
import { ErrorCode, McpError } from "@modelcontextprotocol/sdk/types.js";
import type { ChampionIndex } from "./champion-id";
import { DEFAULT_TIMEOUT_MS, DataSourceError, withTimeout, type DataErrorCode } from "./errors";
import { analysisFields, META_FIELDS, toOpggChampionName } from "./opgg-champion";
import { MATCH_FIELDS, MATCH_LIMIT, PROFILE_FIELDS, profileFromOpgg } from "./opgg-player";
import type { PlayerProfile, Region, RiotId, Role } from "./types";

export const DEFAULT_OPGG_MCP_URL = "https://mcp-api.op.gg/mcp";

export function getOpggUrl(env: Record<string, string | undefined> = process.env): string {
  return env.OPGG_MCP_URL?.trim() || DEFAULT_OPGG_MCP_URL;
}

let clientPromise: Promise<Client> | null = null;

async function connect(): Promise<Client> {
  const client = new Client({ name: "rat-draft", version: "0.1.0" });
  const transport = new StreamableHTTPClientTransport(new URL(getOpggUrl()));
  await withTimeout(client.connect(transport), "opgg");
  return client;
}

/** Reuses one connection across requests; a failed connect is retried next time. */
async function getClient(): Promise<Client> {
  if (!clientPromise) {
    clientPromise = connect().catch((err: unknown) => {
      clientPromise = null;
      throw toDataError(err, "connect");
    });
  }
  return clientPromise;
}

async function resetClient(): Promise<void> {
  const current = clientPromise;
  clientPromise = null;
  if (current) {
    try {
      await (await current).close();
    } catch {
      // connection was already broken
    }
  }
}

function toDataError(err: unknown, what: string): DataSourceError {
  if (err instanceof DataSourceError) return err;
  const message = err instanceof Error ? err.message : String(err);
  let code: DataErrorCode = "network";
  if (err instanceof McpError && err.code === ErrorCode.RequestTimeout) code = "timeout";
  else if (/not\s*found/i.test(message)) code = "not_found";
  else if (/timed? ?out/i.test(message)) code = "timeout";
  else if (err instanceof McpError && err.code !== ErrorCode.ConnectionClosed) code = "bad_response";
  return new DataSourceError("opgg", code, `OP.GG ${what} failed: ${message}`, { cause: err });
}

/** Runs an operation on the shared client; on a transport failure reconnects once and retries. */
async function withClient<T>(what: string, op: (client: Client) => Promise<T>): Promise<T> {
  try {
    return await op(await getClient());
  } catch (first) {
    // Protocol answers (e.g. "Summoner not found", timeouts) are not connection problems.
    const mapped = toDataError(first, what);
    if (mapped.code !== "network") throw mapped;
    await resetClient();
    try {
      return await op(await getClient());
    } catch (second) {
      throw toDataError(second, what);
    }
  }
}

export interface OpggToolInfo {
  name: string;
  description?: string;
  inputSchema: unknown;
}

export async function listOpggTools(): Promise<OpggToolInfo[]> {
  return withClient("tools/list", async (client) => {
    const tools: OpggToolInfo[] = [];
    let cursor: string | undefined;
    do {
      const page = await client.listTools(cursor ? { cursor } : undefined, {
        timeout: DEFAULT_TIMEOUT_MS,
      });
      for (const t of page.tools) {
        tools.push({ name: t.name, description: t.description, inputSchema: t.inputSchema });
      }
      cursor = page.nextCursor;
    } while (cursor);
    return tools;
  });
}

/**
 * Calls an OP.GG tool and returns its text content (OP.GG returns the data as
 * text). Throws a DataSourceError on timeout, transport error or tool error.
 */
export async function callOpggTool(name: string, args: Record<string, unknown>): Promise<string> {
  const result = await withClient(name, (client) =>
    client.callTool({ name, arguments: args }, undefined, { timeout: DEFAULT_TIMEOUT_MS }),
  );

  const content = Array.isArray(result.content) ? result.content : [];
  const text = content
    .filter((c): c is { type: "text"; text: string } => c?.type === "text" && typeof c.text === "string")
    .map((c) => c.text)
    .join("\n");

  if (result.isError) {
    const code = /not\s*found|존재하지/i.test(text) ? "not_found" : "bad_response";
    throw new DataSourceError("opgg", code, `OP.GG ${name} error: ${text.slice(0, 300)}`);
  }
  return text;
}

/**
 * Profile + recent matches → PlayerProfile. The match history is optional:
 * if it fails, the profile is still returned (without recent form/roles).
 */
export async function fetchOpggPlayerProfile(
  riotId: RiotId,
  region: Region,
  index: ChampionIndex,
): Promise<PlayerProfile> {
  const base = { game_name: riotId.gameName, tag_line: riotId.tagLine, region: region.toUpperCase(), lang: "en_US" };
  const [profileText, matchesText] = await Promise.all([
    callOpggTool("lol_get_summoner_profile", { ...base, desired_output_fields: PROFILE_FIELDS }),
    callOpggTool("lol_list_summoner_matches", {
      ...base,
      limit: MATCH_LIMIT,
      desired_output_fields: MATCH_FIELDS,
    }).catch(() => null),
  ]);
  try {
    return profileFromOpgg(profileText, { riotId, region, index, matchesText });
  } catch (err) {
    throw new DataSourceError("opgg", "bad_response", `Could not read OP.GG profile: ${String(err)}`, { cause: err });
  }
}

/** Raw lol_get_champion_analysis text for a champion (English name) in a role. */
export function fetchOpggChampionAnalysis(englishName: string, role: Role): Promise<string> {
  return callOpggTool("lol_get_champion_analysis", {
    game_mode: "ranked",
    champion: toOpggChampionName(englishName),
    position: role,
    desired_output_fields: analysisFields(role),
  });
}

/** Raw lol_get_lane_matchup_guide text (JSON) for "my" champion vs an opponent. */
export function fetchOpggMatchupGuide(role: Role, myEnglishName: string, opponentEnglishName: string): Promise<string> {
  return callOpggTool("lol_get_lane_matchup_guide", {
    position: role,
    my_champion: toOpggChampionName(myEnglishName),
    opponent_champion: toOpggChampionName(opponentEnglishName),
  });
}

/** Closes the shared connection (used by scripts). */
export async function closeOpgg(): Promise<void> {
  await resetClient();
}

/** Raw lol_list_lane_meta_champions text for every role. */
export function fetchOpggLaneMeta(): Promise<string> {
  return callOpggTool("lol_list_lane_meta_champions", { position: "all", desired_output_fields: META_FIELDS });
}
